template <typename T>
bool Gochart<T>::HandleTrigger(EState state, const internal::TriggerEntry& trigger_entry)
{
    switch (state)
    {
        case EState::__Root__:
            return Gochart_HandleTrigger(trigger_entry);
        case EState::Root:
            return StateRoot_HandleTrigger(trigger_entry);
        case EState::Door:
            return StateDoor_HandleTrigger(trigger_entry);
        case EState::DoorInactive:
            return StateDoorInactive_HandleTrigger(trigger_entry);
        case EState::DoorActive:
            return StateDoorActive_HandleTrigger(trigger_entry);
        case EState::DoorOpened:
            return StateDoorOpened_HandleTrigger(trigger_entry);
        case EState::DoorMoving:
            return StateDoorMoving_HandleTrigger(trigger_entry);
        case EState::DoorClosed:
            return StateDoorClosed_HandleTrigger(trigger_entry);
        case EState::Window:
            return StateWindow_HandleTrigger(trigger_entry);
        case EState::WindowInitial:
            return StateWindowInitial_HandleTrigger(trigger_entry);
        case EState::WindowIdle:
            return StateWindowIdle_HandleTrigger(trigger_entry);
        case EState::__Invalid__:
            break;
    }

    GOCHART_DEBUG_BREAK;
    return false;
}

template <typename T>
void Gochart<T>::ProcessTrigger(EState state, const internal::TriggerEntry& trigger_entry)
{
    // We go over each state starting from the current to see if they would handle the state.
    while (state != EState::__Invalid__)
    {
        // If this particular state handles the trigger, we stop bubbling up.
        if (HandleTrigger(state, trigger_entry))
        {
            break;
        }
        state = internal::GetParentState(state);
    }
}

	

