	template <typename T>
	bool Gochart<T>::StateDoorOpened_HandleTrigger(const internal::TriggerEntry& trigger_entry)
	{
		switch (trigger_entry.Trigger)
		{
			case ETrigger::Update:
				{
					// Get the trigger data.
					const auto& data = std::get<internal::UpdateData>(trigger_entry.Data);
					if (!StateDoorOpened_EvaluateCaptureConditionForUpdate(data.tick))
					{
											return false;
					}

					CaptureTrigger(EState::DoorOpened, ETrigger::Update, &data);
					return true;
				}
			case ETrigger::ActivateDoorActuator:
				// State DoorOpened doesn't handle trigger ActivateDoorActuator.
				return false;
			case ETrigger::ToggleDoor:
				{
					// Get the trigger data.
					const auto& data = std::get<internal::ToggleDoorData>(trigger_entry.Data);

					ProcessTransition(EState::DoorOpened,
											  EState::DoorMoving,
											  ETrigger::ToggleDoor,
											  &data);
					return true;
				}
			case ETrigger::DoorMovingDone:
				// State DoorOpened doesn't handle trigger DoorMovingDone.
				return false;
			case ETrigger::TransferToWindow:
				// State DoorOpened doesn't handle trigger TransferToWindow.
				return false;
			case ETrigger::__Invalid__:
				break;
		}

		GOCHART_DEBUG_BREAK;
		return false;
	}

	

