	template <typename T>
	void Gochart<T>::CallEnterReaction(EState state, ETrigger trigger, const void* trigger_data)
	{
		switch (state)
		{
			case EState::__Root__:
				Gochart_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::Root:
				StateRoot_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::Door:
				StateDoor_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::DoorInactive:
				StateDoorInactive_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::DoorActive:
				StateDoorActive_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::DoorOpened:
				StateDoorOpened_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::DoorMoving:
				StateDoorMoving_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::DoorClosed:
				StateDoorClosed_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::Window:
				StateWindow_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::WindowInitial:
				StateWindowInitial_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::WindowIdle:
				StateWindowIdle_CallEnterReaction(trigger, trigger_data);
				return;
			case EState::__Invalid__:
				break;
		}

		GOCHART_DEBUG_BREAK;
	}

