	template <typename T>
	void Gochart<T>::CallCaptureReaction(EState state, ETrigger trigger, const void* trigger_data)
	{
		switch (state)
		{
			case EState::__Root__:
				Gochart_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::Root:
				StateRoot_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::Door:
				StateDoor_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::DoorInactive:
				StateDoorInactive_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::DoorActive:
				StateDoorActive_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::DoorOpened:
				StateDoorOpened_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::DoorMoving:
				StateDoorMoving_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::DoorClosed:
				StateDoorClosed_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::Window:
				StateWindow_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::WindowInitial:
				StateWindowInitial_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::WindowIdle:
				StateWindowIdle_CallCaptureReaction(trigger, trigger_data);
				return;
			case EState::__Invalid__:
				break;
		}

		GOCHART_DEBUG_BREAK;
	}

