EState GetParentState(EState state) {
    switch (state) {
        case EState::__Root__:
            return EState::__Invalid__;
        case EState::Root:
            return EState::__Root__;
        case EState::Door:
            return EState::Root;
        case EState::DoorInactive:
            return EState::Door;
        case EState::DoorActive:
            return EState::Door;
        case EState::DoorOpened:
            return EState::DoorActive;
        case EState::DoorMoving:
            return EState::DoorActive;
        case EState::DoorClosed:
            return EState::DoorActive;
        case EState::Window:
            return EState::Root;
        case EState::WindowInitial:
            return EState::Window;
        case EState::WindowIdle:
            return EState::Window;
        case EState::__Invalid__:
            break;
    }

    GOCHART_DEBUG_BREAK;
    return EState::__Invalid__;
}

EState GetDefaultChild(EState state)
{
    switch (state) {
        case EState::__Root__:
            return EState::Root;
        case EState::Root:
            return EState::Door;
        case EState::Door:
            return EState::DoorInactive;
        case EState::DoorInactive:
            return EState::__Invalid__;
        case EState::DoorActive:
            return EState::DoorOpened;
        case EState::DoorOpened:
            return EState::__Invalid__;
        case EState::DoorMoving:
            return EState::__Invalid__;
        case EState::DoorClosed:
            return EState::__Invalid__;
        case EState::Window:
            return EState::WindowInitial;
        case EState::WindowInitial:
            return EState::__Invalid__;
        case EState::WindowIdle:
            return EState::__Invalid__;
        case EState::__Invalid__:
            break;
    }

    GOCHART_DEBUG_BREAK;
    return EState::__Invalid__;
}

